         lead:'reverseArrayを呼び出したあと、配列を1行ずつ出力する処理を書きなさい(4,3,2,1の順になるはず)。',
         answers:['reverseArray(a,4);\nfor(int i=0;i<4;i++){\ncout<<a[i]<<endl;\n}'],
