         lead:'"A"でHP80のhero1と、"B"でHP60のhero2を生成し、hero1がhero2より強い(isStrongerThan)かどうかの結果を出力する処理を書きなさい。',
         answers:['Hero hero1("A",80);\nHero hero2("B",60);\ncout << hero1.isStrongerThan(hero2) << endl;'],
