         lead:'"A"のみでhero1、"B"と80でhero2を生成し、両方のgetHP()の合計を出力する処理を書きなさい(130になるはず)。',
         answers:['Hero hero1("A");\nHero hero2("B",80);\ncout << hero1.getHP() + hero2.getHP() << endl;'],
