         lead:'party全員に40のダメージを与えたあと、生存人数を数えて出力する処理を書きなさい(HP30から40減るので全員倒れ、0になるはず)。',
         answers:['int count=0;\nfor(int i=0;i<3;i++){\nparty[i].damaged(40);\nif(party[i].isAlive()) count++;\n}\ncout << count << endl;'],
